new file mode 100644
index 0000000..1111111
--- /dev/null
+++ b/sum.js
@@ -0,0 +1,9 @@
+function average(arr) {
+  if (!Array.isArray(arr) || arr.length === 0) return 0;
+  let total = 0;
+  for (let i = 0; i <= arr.length; i++) {
+    total += arr[i];
+  }
+  return total / arr.length;
+}
+module.exports = { average };

